CREATE TYPE "ProductCategory" AS ENUM ('FUEL', 'DEF', 'LUBRICANTS', 'FLUIDS', 'RETAIL', 'ACCESSORIES', 'SERVICES', 'EV_CHARGING', 'OTHER');
CREATE TYPE "UnitOfMeasure" AS ENUM ('LITRE', 'KILOGRAM', 'PIECE', 'BOX', 'UNIT', 'KWH');
CREATE TYPE "TankType" AS ENUM ('UNDERGROUND', 'ABOVE_GROUND');
CREATE TYPE "DipMethod" AS ENUM ('MANUAL', 'ATG');
CREATE TYPE "EquipmentStatus" AS ENUM ('ACTIVE', 'INACTIVE');
CREATE TABLE "stations" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "address_line_1" TEXT NOT NULL, "city" TEXT NOT NULL, "state" TEXT NOT NULL, "postal_code" TEXT NOT NULL, "phone" TEXT, "gstin" TEXT, "opening_time" TEXT, "closing_time" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "stations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "category" "ProductCategory" NOT NULL, "unit" "UnitOfMeasure" NOT NULL, "inventory_tracked" BOOLEAN NOT NULL DEFAULT true, "tank_linked" BOOLEAN NOT NULL DEFAULT false, "meter_linked" BOOLEAN NOT NULL DEFAULT false, "is_service" BOOLEAN NOT NULL DEFAULT false, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "products_pkey" PRIMARY KEY ("id"));
CREATE TABLE "station_configurations" ("id" TEXT NOT NULL, "station_id" TEXT NOT NULL, "version" INTEGER NOT NULL, "effective_from" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "station_configurations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "tanks" ("id" TEXT NOT NULL, "configuration_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "code" TEXT NOT NULL, "nominal_capacity" DECIMAL(12,3) NOT NULL, "working_capacity" DECIMAL(12,3) NOT NULL, "opening_stock" DECIMAL(12,3) NOT NULL DEFAULT 0, "tank_type" "TankType" NOT NULL, "dip_method" "DipMethod" NOT NULL, "status" "EquipmentStatus" NOT NULL DEFAULT 'ACTIVE', CONSTRAINT "tanks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "dispensers" ("id" TEXT NOT NULL, "configuration_id" TEXT NOT NULL, "code" TEXT NOT NULL, "location" TEXT, "status" "EquipmentStatus" NOT NULL DEFAULT 'ACTIVE', CONSTRAINT "dispensers_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nozzles" ("id" TEXT NOT NULL, "dispenser_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "code" TEXT NOT NULL, "opening_meter" DECIMAL(14,3) NOT NULL DEFAULT 0, "status" "EquipmentStatus" NOT NULL DEFAULT 'ACTIVE', CONSTRAINT "nozzles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nozzle_tanks" ("nozzle_id" TEXT NOT NULL, "tank_id" TEXT NOT NULL, CONSTRAINT "nozzle_tanks_pkey" PRIMARY KEY ("nozzle_id", "tank_id"));
CREATE UNIQUE INDEX "stations_organization_id_code_key" ON "stations"("organization_id", "code"); CREATE INDEX "stations_organization_id_idx" ON "stations"("organization_id"); CREATE UNIQUE INDEX "products_organization_id_code_key" ON "products"("organization_id", "code"); CREATE INDEX "products_organization_id_idx" ON "products"("organization_id"); CREATE UNIQUE INDEX "station_configurations_station_id_version_key" ON "station_configurations"("station_id", "version"); CREATE INDEX "station_configurations_station_id_active_idx" ON "station_configurations"("station_id", "active"); CREATE UNIQUE INDEX "tanks_configuration_id_code_key" ON "tanks"("configuration_id", "code"); CREATE UNIQUE INDEX "dispensers_configuration_id_code_key" ON "dispensers"("configuration_id", "code"); CREATE UNIQUE INDEX "nozzles_dispenser_id_code_key" ON "nozzles"("dispenser_id", "code");
ALTER TABLE "stations" ADD CONSTRAINT "stations_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "products" ADD CONSTRAINT "products_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "station_configurations" ADD CONSTRAINT "station_configurations_station_id_fkey" FOREIGN KEY ("station_id") REFERENCES "stations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "tanks" ADD CONSTRAINT "tanks_configuration_id_fkey" FOREIGN KEY ("configuration_id") REFERENCES "station_configurations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "tanks" ADD CONSTRAINT "tanks_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "dispensers" ADD CONSTRAINT "dispensers_configuration_id_fkey" FOREIGN KEY ("configuration_id") REFERENCES "station_configurations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "nozzles" ADD CONSTRAINT "nozzles_dispenser_id_fkey" FOREIGN KEY ("dispenser_id") REFERENCES "dispensers"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "nozzles" ADD CONSTRAINT "nozzles_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "nozzle_tanks" ADD CONSTRAINT "nozzle_tanks_nozzle_id_fkey" FOREIGN KEY ("nozzle_id") REFERENCES "nozzles"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "nozzle_tanks" ADD CONSTRAINT "nozzle_tanks_tank_id_fkey" FOREIGN KEY ("tank_id") REFERENCES "tanks"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
